To sort a list of integers in $O(n)$ time when the range of elements is small and known, we can use **Counting Sort**.

### 1. Counting Sort Algorithm (modified for negative numbers)

```c
void countingSort(int arr[], int n) {
    int max = arr[0], min = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max) max = arr[i];
        if (arr[i] < min) min = arr[i];
    }
    int range = max - min + 1;
    int* count = (int*)calloc(range, sizeof(int));
    int* output = (int*)malloc(n * sizeof(int));

    for (int i = 0; i < n; i++) {
        count[arr[i] - min]++;
    }
    for (int i = 1; i < range; i++) {
        count[i] += count[i - 1];
    }
    for (int i = n - 1; i >= 0; i--) {
        output[count[arr[i] - min] - 1] = arr[i];
        count[arr[i] - min]--;
    }
    for (int i = 0; i < n; i++) {
        arr[i] = output[i];
    }
    free(count); free(output);
}

```

### 2. Illustration with Example: `3, 8, 5, 4, 1, 9, -2`
- **Step 1:** Find min and max: $\min = -2$, $\max = 9$. Range = $9 - (-2) + 1 = 12$.
- **Step 2:** Create count array of size 12 initialized to 0. 
- **Step 3:** Populate frequency counts:
  `count[0]` (for -2) = 1, `count[3]` (for 1) = 1, `count[5]` (for 3) = 1, `count[6]` (for 4) = 1, `count[7]` (for 5) = 1, `count[10]` (for 8) = 1, `count[11]` (for 9) = 1.
- **Step 4:** Compute prefix sums of `count` and place elements in the sorted output array: `[-2, 1, 3, 4, 5, 8, 9]`.

### 3. Justification of O(n) Complexity
Counting sort takes $O(n + k)$ where $n$ is the number of elements and $k$ is the range of input values. Since the range $k = 12$ is small and constant relative to $n$, the overall running time is linear, i.e., $O(n)$.

### Linked List Representation of a Term
Each node in the linked list represents a term: `coeff` (coefficient), `power` (exponent), and a `next` pointer.

```c
struct Node {
    int coeff;
    int power;
    struct Node* next;
};

struct Node* addPolynomials(struct Node* poly1, struct Node* poly2) {
    struct Node* result = NULL;
    while (poly1 != NULL && poly2 != NULL) {
        if (poly1->power > poly2->power) {
            insertTerm(&result, poly1->coeff, poly1->power);
            poly1 = poly1->next;
        } else if (poly1->power < poly2->power) {
            insertTerm(&result, poly2->coeff, poly2->power);
            poly2 = poly2->next;
        } else {
            int sumCoeff = poly1->coeff + poly2->coeff;
            if (sumCoeff != 0) {
                insertTerm(&result, sumCoeff, poly1->power);
            }
            poly1 = poly1->next;
            poly2 = poly2->next;
        }
    }
    while (poly1 != NULL) {
        insertTerm(&result, poly1->coeff, poly1->power);
        poly1 = poly1->next;
    }
    while (poly2 != NULL) {
        insertTerm(&result, poly2->coeff, poly2->power);
        poly2 = poly2->next;
    }
    return result;
}

```

### Step-by-Step Addition of the given Polynomials:
- **Poly 1:** $4x^3 + 7x^2 + 9$ 
- **Poly 2:** $15x^3 + 2x^2 + 4$
- **Step 1:** Add terms with exponent 3: $(4 + 15)x^3 = 19x^3$
- **Step 2:** Add terms with exponent 2: $(7 + 2)x^2 = 9x^2$
- **Step 3:** Add terms with exponent 0: $(9 + 4) = 13$
- **Result:** $19x^3 + 9x^2 + 13$
